css:
/* 全套模板共用。字体、字号、颜色只在 CSS 中定义。 */
.term-art {
  --theme-color: var(--color-primary, #234f3c);
  color: var(--theme-color);
}
.term-art .template-text {
  fill: currentColor;
  font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
  font-size: 36px;
  font-weight: 400;
  dominant-baseline: text-before-edge;
}
.term-art .term-title {
  font-family: "Microsoft YaHei", "PingFang SC", sans-serif;
  font-size: 86px;
  letter-spacing: 12px;
}
.term-art .day-number {
  font-family: Arial, sans-serif;
  font-size: 226px;
  font-weight: 700;
  letter-spacing: -12px;
}
.term-art .date-caption {
  font-family: Arial, "Microsoft YaHei", sans-serif;
  font-size: 27px;
  letter-spacing: 4px;
  opacity: .65;
}
.term-art .poem {
  font-family: "Noto Serif CJK SC", SimSun, serif;
  font-size: 28px;
  letter-spacing: 5px;
}
.term-art .eyebrow {
  font-size: 20px;
  letter-spacing: 8px;
  opacity: .55;
}
